using BetaFit.Desktop.Services;
namespace BetaFit.Desktop.Controls;
public sealed class UcHeader:UserControl {private readonly IBetaFitApiService? _api;private readonly Label status=new();public UcHeader():this(null,null){}public UcHeader(IBetaFitApiService? api,Session? session){_api=api;Dock=DockStyle.Top;Height=64;BackColor=Color.FromArgb(24,29,37);var title=new Label{Text="Painel administrativo",ForeColor=Color.White,Font=new Font("Segoe UI Semibold",14),Dock=DockStyle.Left,Width=260,TextAlign=ContentAlignment.MiddleLeft};var user=new Label{Text=session?.UserName??"Designer",ForeColor=Color.Gainsboro,Dock=DockStyle.Right,Width=180,TextAlign=ContentAlignment.MiddleRight};status.Dock=DockStyle.Right;status.Width=120;status.TextAlign=ContentAlignment.MiddleCenter;Controls.Add(user);Controls.Add(status);Controls.Add(title);if(_api!=null)Load+=async(_,_)=>await RefreshStatusAsync();}public async Task RefreshStatusAsync(){if(_api==null)return;var online=await _api.IsApiOnlineAsync();status.Text=online?"● API Online":"● API Offline";status.ForeColor=online?Color.LightGreen:Color.IndianRed;}}